    {
      "source_id": "h10",
      "actor": "assistant",
      "role": "observation",
      "fact": "Line L1002 is suspended with a suspension_start_date of 2025-02-25, and its contract_end_date is 2026-12-31 (not in the past)."
    },
    {
      "source_id": "h34",
      "actor": "assistant",
      "role": "observation",
      "fact": "Bill B1234321, associated with line L1002, has been paid (status: Paid)."
