      "fact": "Customer C1001 has an active account status."
    },
    {
      "source_id": "h14",
      "actor": "assistant",
      "role": "observation",
      "fact": "No other bills are in AWAITING_PAYMENT status for customer C1001."
    },
    {
      "source_id": "q7",
      "actor": "system",
      "role": "policy",
      "fact": "The assistant is allowed to resume a line if the user has paid all overdue bills and the contract end date is not in the past."
